//! JMAP Session/account discovery. Discovered URLs never expand signed origins.
use crate::*;
pub fn request(url:&str,credential:&str,then:&str)->Value{accounts::authenticated(http::get(url,then),credential)}
pub fn parse(r:&Value)->Result<Value,String>{if r["status"]!=200{return Err("JMAP Session discovery failed".into())}let raw=http::parse_json(r)?;if !raw["capabilities"]["urn:ietf:params:jmap:mail"].is_object(){return Err("Provider does not advertise JMAP Mail".into())}let endpoint=raw["apiUrl"].as_str().ok_or("Missing JMAP API URL")?;email::Mailbox::new(endpoint,"validate","validate","validate")?;let accounts=raw["accounts"].as_object().filter(|a|a.len()<=8).ok_or("Provider account list exceeds8")?;let mut out=Vec::new();for(id,a)in accounts{email_content::ident(id)?;if !a["accountCapabilities"]["urn:ietf:params:jmap:mail"].is_object(){continue}let label=email_content::text(&a["name"],120,false)?;let readonly=a["isReadOnly"].as_bool().ok_or("Missing account access mode")?;out.push(json!({"id":id,"name":label,"read_only":readonly}));}if out.is_empty(){return Err("No usable JMAP mail account".into())}let upload=raw["uploadUrl"].as_str().filter(|s|s.len()<=1024&&s.starts_with("https://")).unwrap_or("");let download=raw["downloadUrl"].as_str().filter(|s|s.len()<=2048&&s.starts_with("https://")).unwrap_or("");Ok(json!({"api_url":endpoint,"accounts":out,"upload_url":upload,"download_url":download,"can_submit":raw["capabilities"]["urn:ietf:params:jmap:submission"].is_object()}))}
#[cfg(test)]mod tests{use super::*;#[test]fn session_projects_accounts_without_tokens_and_never_grants_origins(){let raw=json!({"apiUrl":"https://mail.example.org/jmap","capabilities":{"urn:ietf:params:jmap:mail":{},"urn:ietf:params:jmap:submission":{}},"accounts":{"a":{"name":"Personal","isReadOnly":false,"accountCapabilities":{"urn:ietf:params:jmap:mail":{}}}},"uploadUrl":"https://uploads.example.org/{accountId}","downloadUrl":"https://mail.example.org/{accountId}/{blobId}/{name}?type={type}","access_token":"must not appear"});let v=parse(&json!({"status":200,"text":raw.to_string()})).unwrap();assert_eq!(v["accounts"][0]["id"],"a");assert!(v.get("access_token").is_none());assert!(v.get("origins").is_none());let mut bad=raw;bad["apiUrl"]=json!("https://secret@evil.example.org/jmap");assert!(parse(&json!({"status":200,"text":bad.to_string()})).is_err());}}
